import { useMemo, useState } from 'react';
import { JSONSchemaCustom, SchemaApiJsonPage } from '@/components/schema';
import { Button } from '@arco-design/web-react';
import { useObserver } from 'mobx-react-lite';
import { toJS } from 'mobx';
import FeatchStore from '@/store/featch';



const Index = () => {

    const [featch] = useState(() => new FeatchStore())


    return useObserver(() => {

        const schema = useMemo(() => {

            return {
                type: "object",
                properties: {
                    "id": {
                        title: "标签ID",
                        type: "string",
                    },
                    "appId": {
                        title: "所属租户",
                        type: "string",
                        fieldProps: {
                            "readOnly": true
                        }
                    },
                    "moduleId": {
                        title: "模块id",
                        columnProps: {
                            width: 100,
                            ellipsis: true,
                        },
                        fieldProps: {
                            "readOnly": true
                        }
                    },
                    "status": {
                        "title": "组件状态",
                        "columnProps": {
                            width: 100,
                        },
                        "enum": [
                            { value: 0, label: "已停用", color: "#f53f3f" },
                            { value: 1, label: "正常", color: "arcoblue" },
                            { value: 2, label: "审核中", color: "#ffb400" },
                        ]
                    },
                    "pluginId": {
                        "type": "string",
                        "title": "所属插件",
                        "format": "selector",
                        "fieldProps": {
                            "type": "plugins"
                        },
                        "enum": featch.options("plugins"),
                        "maxLength": 50,
                        "show": {
                            "source!{}": ["context"]
                        }
                    },
                    "componentId": {
                        title: "所属组件库",
                        type: "string",
                        format: "selector",
                        fieldProps: {
                            type: "component"
                        },
                    },
                    "imgUrl": {
                        "title": "组件图片",
                        "type": "string",
                        "format": "image",
                    },
                    "componentName": {
                        title: "所属组件库",
                        type: "string",
                    },
                    "PublicTagModule": {
                        "title": "组件标签",
                        type: "array",
                        format: "selector",
                        fieldProps: {
                            mode: "multiple",
                            type: "TagModule"
                        },
                        columnProps: {
                            render: (data) => {
                                if(data){
                                    return data.map((o) => o.name).join(',')
                                }
                                return ""
                            }
                        }
                    },
                    // "labels": {
                    //     title: "所属标签",
                    //     type: "string"
                    // },
                    "name": {
                        title: "组件名",
                        type: "string",
                        fieldProps: {
                            "readOnly": true
                        }
                    },
                    "nickname": {
                        title: "模块名称",
                        type: "string",
                    },
                    // "jsxRender": {
                    //     type: "string"
                    // },
                    "description": {
                        "title": "说明",
                        "format": "text",
                    },
                    "updatedAt": {
                        title: "更新时间",
                        type: "string",
                        columnProps: {
                            width: 180
                        }
                    },
                    "userId": {
                        "title": "更新人",
                        "type": "string",
                        columnProps: {
                            width: 80
                        }
                    }
                }
            } as JSONSchemaCustom
        },[toJS(featch.options("plugins"))])


        return (
            <div>
                <SchemaApiJsonPage
                    apijson={{
                        tableName: "PublicModule",
                        uniqueKey: "id",
                        // notDel: true,
                        notAdd: true,
                        getParams: (item) => {
                            if(item.PublicTagModule){
                                item.PublicTagModule = item.PublicTagModule.map((o) => o.id);
                            }
                            return item;
                        },
                        findParams: {
                            "@order": "updatedAt-",
                        }
                    }}
                    joins={[
                        {
                            tableName: "Component",
                            type: "One",
                            uniqueKey: "id",
                            foreignKey: "id",
                            columns: ["name:componentName"],
                            relationKey: 'componentId'
                        },
                        {
                            tableName: "TagModule",
                            type: "ToMany",
                            foreignKey: "id",
                            relationKey: "id",
                            toTableName: "PublicTagModule",
                            toTableKey: "id",
                            toForeignKey: "mId",
                            toRelationKey: "tagId",
                            columns: ["id", "name"]
                        }
                    ]}
                    tableFilterKeys={["appId", "moduleId",  "pluginId", "status", "componentName", "name", "nickname", "PublicTagModule", "description", "updatedAt", "userId"]}
                    queryFilterKeys={["appId", "status", "moduleId", "componentId", "PublicTagModule", "name", "nickname"]}
                    formFilterKeys={["appId", "name", "pluginId", "status", "componentId", "imgUrl", "PublicTagModule"]}
                    schemForm={{
                        generagteProps: {
                            cols: 24
                        }
                    }}
                    getOperationList={(list, item) => {
    
                        return [
                            ...list,
                            { 
                                title: "进入",
                                onClick: () => {
                                    
                                }
                            }
                        ]
                    }}
                    modalProps={{
                        style: { width: 600 }
                    }}
                    schema={schema}
                />
            </div>
        )
    })
}

export default Index;